impl Solution{pub fn full_justify(w:Vec<String>,width:i32)->Vec<String>{let width=width as usize;let mut o=vec![];let mut i=0;while i<w.len(){let(mut j,mut len)=(i,0);while j<w.len()&&len+w[j].len()+j-i<=width{len+=w[j].len();j+=1}let gaps=j-i-1;let mut line=String::new();if j==w.len()||gaps==0{for k in i..j{if k>i{line.push(' ')}line.push_str(&w[k]);}line.push_str(&" ".repeat(width-line.len()));}else{let s=width-len;let(b,e)=(s/gaps,s%gaps);for k in i..j{line.push_str(&w[k]);if k<j-1{line.push_str(&" ".repeat(b+usize::from(k-i<e)));}}}o.push(line);i=j;}o}}
